# --- QOperator (QLinearConv/QLinearMatMul/QGemm) family ---------------------


def _qop_not_eligible(
    graph: onnx.GraphProto,
    chains: List[_QOpChain],
    gated_chains: List[_QOpGatedChain],
) -> List[str]:
    matched_ids: Set[int] = set()
    for chain in chains:
        matched_ids.add(id(chain.producer.node))
        matched_ids.add(id(chain.consumer.node))
    for gchain in gated_chains:
        matched_ids.add(id(gchain.producer_a.weight.node))
        matched_ids.add(id(gchain.producer_b.weight.node))
        matched_ids.add(id(gchain.consumer.node))
    not_eligible = []
    for node in graph.node:
        if node.op_type not in ("QLinearConv", "QLinearMatMul", "QGemm"):
            continue
        if id(node) in matched_ids:
            continue
        not_eligible.append(f"{node.op_type} '{_node_label(node)}'")
    return not_eligible


def _analyze_structured_pruning_qoperator(
    model: Union[str, onnx.ModelProto],
    sparsity: float = 0.5,
    importance_norm: _ImportanceNorm = "l2",
) -> PruningSensitivityReport:
    """Dry-run mirror of :func:`apply_structured_pruning_qoperator` -- same
    matching (:func:`_find_qop_chains`), touched-role bookkeeping (a chain
    sharing a weight -- on either side -- with an earlier one in
    `_find_qop_chains`'s own return order is reported `would_drop=0`/
    `margin=None`, exactly the "left completely untouched" outcome the real
    call gives it too), keep-count, and importance
    (:func:`_qop_dequantized_nk` + :func:`_qdq_channel_importance`) logic,
    reused directly, but `model` is never mutated. `family` is
    ``"qoperator_conv"`` (a ``QLinearConv`` producer) or
    ``"qoperator_matmul"`` (a ``QLinearMatMul``/``QGemm`` producer) --
    mirroring the QDQ family's own identical two-way split.

    A degenerate chain naming the exact same weight in both the producer and
    consumer role gets no report row at all, mirroring
    :func:`_analyze_structured_pruning_qdq`'s own identical treatment.

    Also mirrors the real call's own gated (SwiGLU/GeGLU/ReGLU) pair support
    (:func:`_find_qop_gated_chains`, `family="qoperator_matmul_gated"`) --
    same touched-role/keep-count treatment as an ordinary QOperator chain
    above, just against the combined (root-sum-square, or plain sum for L1)
    importance of both producers (:func:`_qop_gated_channel_importance`),
    and reported as one row per gated pair (`label` joining both producers'
    own labels, mirroring :func:`_chain_label`'s own plain-float convention
    and :func:`_analyze_structured_pruning_qdq`'s own identical gated-pair
    treatment).

    Subgraph-aware (:func:`_iter_subgraphs`, see this module's own
    "Subgraph recursion" section comment), the dry-run mirror of
    :func:`apply_structured_pruning_qoperator`'s own subgraph awareness:
    `layers`/`not_eligible` are aggregated across every graph, and
    `producer_touched`/`consumer_touched` are reset per graph.
    """
    if not (0.0 <= sparsity < 1.0):
        raise ValueError(f"sparsity must be in [0, 1), got {sparsity}")
    _validate_importance_norm(importance_norm)
    if isinstance(model, str):
        model = onnx.load(model, load_external_data=False)

    layers: List[PruningLayerSensitivity] = []
    not_eligible: List[str] = []

    for graph in _iter_subgraphs(model.graph):
        chains = _find_qop_chains(graph)
        gated_chains = _find_qop_gated_chains(graph)
        not_eligible.extend(_qop_not_eligible(graph, chains, gated_chains))
        if not chains and not gated_chains:
            continue

        producer_touched: Set[str] = set()
        consumer_touched: Set[str] = set()

        for chain in chains:
            p, c = chain.producer, chain.consumer
            p_key = p.w_init.name
            c_key = c.w_init.name
            if p_key == c_key:
                continue  # degenerate (the same weight in both roles) -- no report row

            label = _node_label(p.node)
            family = "qoperator_conv" if p.op_kind == "conv" else "qoperator_matmul"
            n = chain.n_channels

            if p_key in producer_touched or c_key in consumer_touched:
                layers.append(
                    PruningLayerSensitivity(
                        label=label,
                        family=family,
                        total=n,
                        would_drop=0,
                        margin=None,
                        importance_min=0.0,
                        importance_max=0.0,
                    )
                )
                continue  # a shared/tied weight another chain already claimed

            keep_count = max(1, n - round(n * sparsity))
            if keep_count >= n:
                layers.append(
                    PruningLayerSensitivity(
                        label=label,
                        family=family,
                        total=n,
                        would_drop=0,
                        margin=None,
                        importance_min=0.0,
                        importance_max=0.0,
                    )
                )
                continue  # rounds down to nothing for this chain -- no-op

            w_nk = _qop_dequantized_nk(p)
            importance = _qdq_channel_importance(w_nk, importance_norm)
            keep = np.sort(np.argsort(-importance, kind="stable")[:keep_count])
            keep_mask = np.zeros(n, dtype=bool)
            keep_mask[keep] = True

            layers.append(
                PruningLayerSensitivity(
                    label=label,
                    family=family,
                    total=n,
                    would_drop=int(n - keep_count),
                    margin=_normalized_margin(importance, keep_mask),
                    importance_min=float(importance.min()),
                    importance_max=float(importance.max()),
                )
            )

            producer_touched.add(p_key)
            consumer_touched.add(c_key)

        for gchain in gated_chains:
            pa, pb, c = gchain.producer_a, gchain.producer_b, gchain.consumer
            pa_key = pa.weight.w_init.name
            pb_key = pb.weight.w_init.name
            c_key = c.w_init.name
            if pa_key == pb_key or pa_key == c_key or pb_key == c_key:
                continue  # degenerate (a weight tied across two roles) -- no report row

            label = f"{_node_label(pa.weight.node)} + {_node_label(pb.weight.node)}"
            family = "qoperator_matmul_gated"
            n = gchain.n_channels

            if (
                pa_key in producer_touched
                or pb_key in producer_touched
                or c_key in consumer_touched
            ):
                layers.append(
                    PruningLayerSensitivity(
                        label=label,
                        family=family,
                        total=n,
                        would_drop=0,
                        margin=None,
                        importance_min=0.0,
                        importance_max=0.0,
                    )
                )
                continue  # a shared/tied weight another chain already claimed

            keep_count = max(1, n - round(n * sparsity))
            if keep_count >= n:
                layers.append(
                    PruningLayerSensitivity(
                        label=label,
                        family=family,
                        total=n,
                        would_drop=0,
                        margin=None,
                        importance_min=0.0,
                        importance_max=0.0,
                    )
                )
                continue  # rounds down to nothing for this chain -- no-op

            w_a_nk = _qop_dequantized_nk(pa.weight)
            w_b_nk = _qop_dequantized_nk(pb.weight)
            importance = _qop_gated_channel_importance(w_a_nk, w_b_nk, importance_norm)
            keep = np.sort(np.argsort(-importance, kind="stable")[:keep_count])
            keep_mask = np.zeros(n, dtype=bool)
            keep_mask[keep] = True

            layers.append(
                PruningLayerSensitivity(
                    label=label,
                    family=family,
                    total=n,
                    would_drop=int(n - keep_count),
                    margin=_normalized_margin(importance, keep_mask),
                    importance_min=float(importance.min()),
                    importance_max=float(importance.max()),
                )
            )

            producer_touched.add(pa_key)
            producer_touched.add(pb_key)
            consumer_touched.add(c_key)

    return PruningSensitivityReport(layers=layers, not_eligible=not_eligible)


# --- DynamicQuantizeMatMul / MatMulIntegerToFloat family --------------------


def _dynquant_not_eligible(
    graph: onnx.GraphProto,
    chains: List[_DynQuantMatMulChain],
    gated_chains: List[_DynQuantMatMulGatedChain],
) -> List[str]:
    """Extended, alongside :func:`apply_structured_pruning_dynamic_quantize_matmul`'s
    own gated (SwiGLU/GeGLU) pair matching, to also mark a matched gated
    pair's own producers/consumer ineligible -- mirroring
    :func:`_matmul_nbits_not_eligible`'s own identical extension.
    """
    matched_ids: Set[int] = set()
    for chain in chains:
        matched_ids.add(id(chain.producer.node))
        matched_ids.add(id(chain.consumer.node))
    for gchain in gated_chains:
        matched_ids.add(id(gchain.producer_a.node))
        matched_ids.add(id(gchain.producer_b.node))
        matched_ids.add(id(gchain.consumer.node))
    not_eligible = []
    for node in graph.node:
        if node.op_type not in ("DynamicQuantizeMatMul", "MatMulIntegerToFloat"):
            continue
        if id(node) in matched_ids:
            continue
        not_eligible.append(f"{node.op_type} '{_node_label(node)}'")
    return not_eligible


def _analyze_structured_pruning_dynamic_quantize_matmul(
    model: Union[str, onnx.ModelProto],
    sparsity: float = 0.5,
    importance_norm: _ImportanceNorm = "l2",
) -> PruningSensitivityReport:
    """Dry-run mirror of
    :func:`apply_structured_pruning_dynamic_quantize_matmul` -- same
    matching (:func:`_find_dynquant_chains`), touched-role bookkeeping (a
    chain sharing a weight -- on either side -- with an earlier one in
    `_find_dynquant_chains`'s own return order is reported `would_drop=0`/
    `margin=None`, exactly the "left completely untouched" outcome the real
    call gives it too), keep-count, and importance
    (:func:`_dynquant_chain_producer_weight_nk` +
    :func:`_qdq_channel_importance`, ranking the producer's own dequantized-
    or-plain weight row, the exact same helper the real call itself calls,
    never for the actual rewrite) logic, reused directly, but `model` is
    never mutated. Every matched chain has at least one
    `DynamicQuantizeMatMul`/`MatMulIntegerToFloat` side; the other side may
    instead be a plain-float peer (see :class:`_PlainMatMulNBitsPeer`) --
    :func:`_dynquant_chain_side_key` dispatches on which. `family` is always
    ``"dynamic_quantize_matmul"`` -- a single family, unlike the QDQ/
    QOperator families' own Conv/MatMul split (see this module's own
    section comment for why). Unlike the `MatMulNBits` family's own dry-run
    mirror, there is no block-alignment precondition to check at all here
    (`B`'s own codes are plain, unpacked, un-blocked int8/uint8), so every
    genuinely matched chain either gets pruned or is reported already-
    claimed/no-op -- never declined for block-alignment reasons.

    A degenerate chain naming the exact same weight in both the producer
    and consumer role gets no report row at all, mirroring
    :func:`_analyze_structured_pruning_qoperator`'s own identical treatment.

    Also mirrors the real call's own gated (SwiGLU/GeGLU) pair support
    (:func:`_find_dynquant_gated_chains`, `family="dynamic_quantize_matmul_gated"`)
    -- same touched-role/keep-count treatment as an ordinary chain above,
    just against the combined (root-sum-square, or plain sum for L1)
    importance of both producers (:func:`_dynquant_gated_channel_importance`),
    and reported as one row per gated pair (`label` joining both producers'
    own labels, mirroring :func:`_chain_label`'s own plain-float
    convention). No block-alignment precondition applies here either,
    exactly like the plain family's own dry-run mirror above.

    Subgraph-aware (:func:`_iter_subgraphs`, see this module's own
    "Subgraph recursion" section comment), the dry-run mirror of
    :func:`apply_structured_pruning_dynamic_quantize_matmul`'s own subgraph
    awareness: `layers`/`not_eligible` are aggregated across every graph,
    and `producer_touched`/`consumer_touched` are reset per graph.
    """
    if not (0.0 <= sparsity < 1.0):
        raise ValueError(f"sparsity must be in [0, 1), got {sparsity}")
    _validate_importance_norm(importance_norm)
    if isinstance(model, str):
        model = onnx.load(model, load_external_data=False)

    top_value_info_by_name = _shape_inferred_value_info_by_name(model)
    layers: List[PruningLayerSensitivity] = []
    not_eligible: List[str] = []

    for graph in _iter_subgraphs(model.graph):
        value_info_by_name = (
            top_value_info_by_name
            if graph is model.graph
            else _value_info_by_name(graph)
        )
        chains = _find_dynquant_chains(graph, value_info_by_name)
        gated_chains = _find_dynquant_gated_chains(graph, value_info_by_name)
        not_eligible.extend(_dynquant_not_eligible(graph, chains, gated_chains))
        if not chains and not gated_chains:
            continue

        producer_touched: Set[str] = set()
        consumer_touched: Set[str] = set()

        for chain in chains:
            p, c = chain.producer, chain.consumer
            p_key = _dynquant_chain_side_key(p)
            c_key = _dynquant_chain_side_key(c)
            if p_key == c_key:
                continue  # degenerate (the same weight in both roles) -- no report row

            label = _node_label(p.node)
            family = "dynamic_quantize_matmul"
            n = chain.n_channels

            if p_key in producer_touched or c_key in consumer_touched:
                layers.append(
                    PruningLayerSensitivity(
                        label=label,
                        family=family,
                        total=n,
                        would_drop=0,
                        margin=None,
                        importance_min=0.0,
                        importance_max=0.0,
                    )
                )
                continue  # a shared/tied weight another chain already claimed

            keep_count = max(1, n - round(n * sparsity))
            if keep_count >= n:
                layers.append(
                    PruningLayerSensitivity(
                        label=label,
                        family=family,
                        total=n,
                        would_drop=0,
                        margin=None,
                        importance_min=0.0,
                        importance_max=0.0,
                    )
                )
                continue  # rounds down to nothing for this chain -- no-op

            w_nk = _dynquant_chain_producer_weight_nk(p)
            importance = _qdq_channel_importance(w_nk, importance_norm)
            keep = np.sort(np.argsort(-importance, kind="stable")[:keep_count])
            keep_mask = np.zeros(n, dtype=bool)
            keep_mask[keep] = True

            layers.append(
                PruningLayerSensitivity(
                    label=label,
                    family=family,
                    total=n,
                    would_drop=int(n - keep_count),
                    margin=_normalized_margin(importance, keep_mask),
                    importance_min=float(importance.min()),
                    importance_max=float(importance.max()),
                )
            )

            producer_touched.add(p_key)
            consumer_touched.add(c_key)

        for gchain in gated_chains:
            pa, pb, c = gchain.producer_a, gchain.producer_b, gchain.consumer
            pa_key = _dynquant_chain_side_key(pa)
            pb_key = _dynquant_chain_side_key(pb)
            c_key = _dynquant_chain_side_key(c)
            if pa_key == pb_key or pa_key == c_key or pb_key == c_key:
                continue  # degenerate (a weight tied across two roles) -- no report row

            label = f"{_node_label(pa.node)} + {_node_label(pb.node)}"
            family = "dynamic_quantize_matmul_gated"
            n = gchain.n_channels

            if (
                pa_key in producer_touched
                or pb_key in producer_touched
                or c_key in consumer_touched
            ):
                layers.append(
                    PruningLayerSensitivity(
                        label=label,
                        family=family,
                        total=n,
                        would_drop=0,
                        margin=None,
                        importance_min=0.0,
                        importance_max=0.0,
                    )
                )
                continue  # a shared/tied weight another chain already claimed

            keep_count = max(1, n - round(n * sparsity))
            if keep_count >= n:
                layers.append(
                    PruningLayerSensitivity(
                        label=label,
                        family=family,
                        total=n,
                        would_drop=0,
                        margin=None,
                        importance_min=0.0,
                        importance_max=0.0,
                    )
                )
                continue  # rounds down to nothing for this chain -- no-op

            w_a_nk = _dynquant_chain_producer_weight_nk(pa)
            w_b_nk = _dynquant_chain_producer_weight_nk(pb)
            importance = _dynquant_gated_channel_importance(
                w_a_nk, w_b_nk, importance_norm
            )
            keep = np.sort(np.argsort(-importance, kind="stable")[:keep_count])
            keep_mask = np.zeros(n, dtype=bool)
            keep_mask[keep] = True

            layers.append(
                PruningLayerSensitivity(
                    label=label,
                    family=family,
                    total=n,
                    would_drop=int(n - keep_count),
                    margin=_normalized_margin(importance, keep_mask),
                    importance_min=float(importance.min()),
                    importance_max=float(importance.max()),
                )
            )

            producer_touched.add(pa_key)
            producer_touched.add(pb_key)
            consumer_touched.add(c_key)

    return PruningSensitivityReport(layers=layers, not_eligible=not_eligible)


# --- DynamicQuantizeConv (ConvInteger) family -------------------------------


def _conv_integer_not_eligible(
    graph: onnx.GraphProto, chains: List[_ConvIntegerChain]
) -> List[str]:
    matched_ids: Set[int] = set()
    for chain in chains:
        matched_ids.add(id(chain.producer.node))
        # `chain.consumer` is only ever `None` for the classifier-head hop
        # (`chain.matmul_consumer` set instead -- see
        # :class:`_ConvIntegerChain`'s own docstring), whose consumer is a
        # plain MatMul/Gemm, never itself a `ConvInteger` -- so it could
        # never appear in the `graph.node` filter below anyway, and needs
        # no entry here.
        if chain.consumer is not None:
            matched_ids.add(id(chain.consumer.node))
    not_eligible = []
    for node in graph.node:
        if node.op_type != "ConvInteger":
            continue
        if id(node) in matched_ids:
            continue
        not_eligible.append(f"{node.op_type} '{_node_label(node)}'")
    return not_eligible


def _analyze_structured_pruning_dynamic_quantize_conv(
    model: Union[str, onnx.ModelProto],
    sparsity: float = 0.5,
    importance_norm: _ImportanceNorm = "l2",
) -> PruningSensitivityReport:
    """Dry-run mirror of
    :func:`apply_structured_pruning_dynamic_quantize_conv` -- same matching
    (:func:`_find_conv_integer_chains`), touched-role bookkeeping (a chain
    sharing a weight -- on either side -- with an earlier one in
    `_find_conv_integer_chains`'s own return order is reported
    `would_drop=0`/`margin=None`, exactly the "left completely untouched"
    outcome the real call gives it too), keep-count, and importance
    (:func:`_conv_integer_dequantized_nk` + :func:`_qdq_channel_importance`,
    the exact same helper the real call itself calls, never for the actual
    rewrite) logic, reused directly, but `model` is never mutated. `family`
    is always ``"dynamic_quantize_conv"`` -- a single family, mirroring the
    ``DynamicQuantizeMatMul`` family's own single-family choice (see this
    module's own "DynamicQuantizeConv (ConvInteger, ...)" section comment
    for why).

    A degenerate chain naming the exact same weight in both the producer
    and consumer role gets no report row at all, mirroring
    :func:`_analyze_structured_pruning_dynamic_quantize_matmul`'s own
    identical treatment.

    Subgraph-aware (:func:`_iter_subgraphs`, see this module's own
    "Subgraph recursion" section comment), the dry-run mirror of
    :func:`apply_structured_pruning_dynamic_quantize_conv`'s own subgraph
    awareness: `layers`/`not_eligible` are aggregated across every graph,
    and `producer_touched`/`consumer_touched` are reset per graph.
    """
    if not (0.0 <= sparsity < 1.0):
        raise ValueError(f"sparsity must be in [0, 1), got {sparsity}")
    _validate_importance_norm(importance_norm)
    if isinstance(model, str):
        model = onnx.load(model, load_external_data=False)

    layers: List[PruningLayerSensitivity] = []
    not_eligible: List[str] = []

    for graph in _iter_subgraphs(model.graph):
        chains = _find_conv_integer_chains(graph)
        not_eligible.extend(_conv_integer_not_eligible(graph, chains))
        if not chains:
            continue

        producer_touched: Set[str] = set()
        consumer_touched: Set[str] = set()

        for chain in chains:
            p, c = chain.producer, chain.consumer
            mm = chain.matmul_consumer
            p_key = p.w_init.name
            # Exactly one of `c`/`mm` is ever set -- see
            # :class:`_ConvIntegerChain`'s own docstring.
            if c is not None:
                c_key = c.w_init.name
            else:
                assert mm is not None
                c_key = mm[1]
            if p_key == c_key:
                continue  # degenerate (the same weight in both roles) -- no report row

            label = _node_label(p.node)
            family = "dynamic_quantize_conv"
            n = chain.n_channels

            if p_key in producer_touched or c_key in consumer_touched:
                layers.append(
                    PruningLayerSensitivity(
                        label=label,
                        family=family,
                        total=n,
                        would_drop=0,
                        margin=None,
                        importance_min=0.0,
                        importance_max=0.0,
                    )
                )
                continue  # a shared/tied weight another chain already claimed

            keep_count = max(1, n - round(n * sparsity))
            if keep_count >= n:
                layers.append(
                    PruningLayerSensitivity(
                        label=label,
                        family=family,
                        total=n,
                        would_drop=0,
                        margin=None,
                        importance_min=0.0,
                        importance_max=0.0,
                    )
                )
                continue  # rounds down to nothing for this chain -- no-op

            w_nk = _conv_integer_dequantized_nk(p)
            importance = _qdq_channel_importance(w_nk, importance_norm)
            keep = np.sort(np.argsort(-importance, kind="stable")[:keep_count])
            keep_mask = np.zeros(n, dtype=bool)
            keep_mask[keep] = True

            layers.append(
                PruningLayerSensitivity(
                    label=label,
                    family=family,
                    total=n,
                    would_drop=int(n - keep_count),
                    margin=_normalized_margin(importance, keep_mask),
                    importance_min=float(importance.min()),
                    importance_max=float(importance.max()),
                )
            )

            producer_touched.add(p_key)
            consumer_touched.add(c_key)

    return PruningSensitivityReport(layers=layers, not_eligible=not_eligible)


# --- Embedding / lm_head vocabulary family ----------------------------------
#
# Only :func:`apply_embedding_vocab_magnitude_pruning` gets a `_analyze_*`
# counterpart here -- :func:`apply_embedding_vocab_pruning` deliberately
# does not, and that is a considered scope decision, not an oversight:
# every other family this module's dry-run analysis covers has its own
# *data-driven* importance ranking (weight magnitude, a Wanda-style
# calibrated norm, router-gate usage, ...) that a `sparsity` argument
# turns into a keep/drop boundary -- exactly the boundary a `margin`
# means anything for. `apply_embedding_vocab_pruning` has no such ranking
# at all: its `keep_token_ids`/`drop_token_ids` argument *is* the answer,
# supplied directly by the caller, not derived from anything this pass
# could report a "would keep/would drop, how safe" verdict on. Given an
# explicit keep-set, dry-running it would only ever be able to echo the
# caller's own input straight back (`total=vocab_size`,
# `would_drop=vocab_size - len(keep_token_ids)`, verbatim) with no
# `importance`/`margin` signal behind it at all -- not a "what would this
# call do that I don't already know" report, just a restatement of the
# call's own arguments. That isn't the shape
# :class:`PruningLayerSensitivity` exists to carry (see its own `margin`
# field docstring), so it is left unregistered rather than forced into a
# shape that would carry no real information.


def _embedding_not_eligible(
    graph: onnx.GraphProto,
    chain: Optional[_EmbeddingChain],
    input_name: Optional[str],
) -> List[str]:
    """Every `Gather`/`EmbedLayerNormalization`/`GatherBlockQuantized` node
    :func:`_match_embedding_gather`/:func:`_match_embed_layer_norm_producer`/
    :func:`_match_gather_block_quantized_producer` (the exact same three
    per-node matchers :func:`_match_embedding_chain` itself calls) confirm
    structurally embedding-shaped, but that the whole call still declines to
    touch -- every one of them when `chain` is `None` (whether because none
    exist, more than one does and the call can't disambiguate without
    `input_name`, or the sole match's own second-consumer/`lm_head` shape
    wasn't confidently recognized -- :func:`_match_embedding_chain` returns
    `None` for all three), or none at all when `chain` is not `None`
    (:func:`_match_embedding_chain`'s own ``len(matches) != 1`` check
    guarantees the chosen `chain.producer` is the *only* structurally-matching
    node reachable under this same `input_name` in that case). Mirrors
    :func:`_match_embedding_chain`'s own `input_name` filter exactly, so a
    structurally-matching producer reading a *different* graph input than a
    given `input_name` is still reported here -- this call would never touch
    it either.
    """
    initializer_map = _constant_map(graph)
    consumers_of = _consumers_of(graph)
    node_by_output = {out: n for n in graph.node for out in n.output}
    graph_input_names = {i.name for i in graph.input}

    not_eligible = []
    for node in graph.node:
        m = _match_embedding_gather(
            node, initializer_map, consumers_of, graph_input_names, node_by_output
        )
        if m is None:
            m = _match_embed_layer_norm_producer(
                node, initializer_map, consumers_of, graph_input_names, node_by_output
            )
        if m is None:
            m_q = _match_gather_block_quantized_producer(
                node, initializer_map, consumers_of, graph_input_names, node_by_output
            )
            if m_q is not None:
                m = m_q[:3]
        if m is None:
            continue
        _w_name, indices_name, underlying = m
        if input_name is not None and input_name not in (indices_name, underlying):
            continue
        if chain is not None and node is chain.producer:
            continue
        not_eligible.append(f"{node.op_type} '{_node_label(node)}'")
    return not_eligible


def _analyze_embedding_vocab_magnitude_pruning(
    model: Union[str, onnx.ModelProto],
    sparsity: float = 0.5,
    protect_token_ids: Optional[Sequence[int]] = None,
    input_name: Optional[str] = None,
) -> PruningSensitivityReport:
    """Dry-run mirror of :func:`apply_embedding_vocab_magnitude_pruning` --
    same matching (:func:`_match_embedding_chain`), `protect_token_ids`
    validation, keep-count, and importance (combined embedding-row/
    untied-`lm_head`-row L2 norm -- the exact same computation
    :func:`apply_embedding_vocab_magnitude_pruning` itself performs) logic,
    reused directly, but `model` is never mutated.

    Reports at most a *single* :class:`PruningLayerSensitivity`
    (`family` ``"embedding_vocab_magnitude"``, `label` the matched
    `Gather`/`EmbedLayerNormalization` producer's own label,
    `total=vocab_size`) -- unlike every channel/head/expert family above,
    :func:`_match_embedding_chain` matches at most one embedding table per
    graph by construction (an ambiguous multi-producer graph -- whether two
    `Gather`s, two `EmbedLayerNormalization` nodes, or one of each --
    declines the whole call outright rather than guessing which one is
    "the" token embedding, see its own docstring), so there is only ever
    one independently-ranked unit for this family to report at all --
    never zero-or-more the way a chain/head/expert-matching family's own
    `_find_*` can return. Reused verbatim for the fused shape: the report's
    own `family` string, granularity, and every field above mean exactly
    the same thing whichever producer shape matched, so no separate family
    name is introduced for it (see this module's own "Embedding / lm_head
    vocabulary pruning" section comment for the full scope decision).

    Subgraph-aware (:func:`_iter_subgraphs`, see this module's own
    "Subgraph recursion" section comment) exactly the same way
    :func:`apply_embedding_vocab_magnitude_pruning` is -- see
    :func:`_match_embedding_chain_any_graph`'s own docstring: the one
    eligible embedding producer this function requires may live inside a
    nested ``If``/``Loop``/``Scan``/``BeamSearch``-family subgraph, at any
    nesting depth, not only the top-level graph, and the "exactly one
    eligible producer, or decline" rule applies across the whole model.
    `not_eligible` is aggregated across every graph (:func:`_embedding_not_eligible`
    called once per graph, `chain` -- found in at most one of them -- only
    ever excludes its own producer from that one graph's own contribution).
    """
    if not (0.0 <= sparsity < 1.0):
        raise ValueError(f"sparsity must be in [0, 1), got {sparsity}")
    if isinstance(model, str):
        model = onnx.load(model, load_external_data=False)

    _match_graph, chain = _match_embedding_chain_any_graph(model.graph, input_name)
    not_eligible = [
        n
        for graph in _iter_subgraphs(model.graph)
        for n in _embedding_not_eligible(graph, chain, input_name)
    ]
    if chain is None:
        return PruningSensitivityReport(layers=[], not_eligible=not_eligible)

    vocab_size = chain.vocab_size
    assert _match_graph is not None
    initializer_map = _constant_map(_match_graph)
    importance = _embedding_vocab_importance(chain, initializer_map)

    protect = {int(i) for i in (protect_token_ids or ())}
    bad_protect = sorted(i for i in protect if not (0 <= i < vocab_size))
    if bad_protect:
        raise ValueError(
            f"protect_token_ids out of range [0, {vocab_size}): {bad_protect[:5]}"
        )

    keep_count = max(1, min(vocab_size, round(vocab_size * (1.0 - sparsity))))
    keep_count = max(keep_count, len(protect))
    order = np.argsort(-importance)
    keep_set = set(protect)
    for idx in order:
        if len(keep_set) >= keep_count:
            break
        keep_set.add(int(idx))

    keep_mask = np.zeros(vocab_size, dtype=bool)
    keep_mask[sorted(keep_set)] = True

    return PruningSensitivityReport(
        layers=[
            PruningLayerSensitivity(
                label=_node_label(chain.producer),
                family="embedding_vocab_magnitude",
                total=vocab_size,
                would_drop=int(vocab_size - len(keep_set)),
                margin=_normalized_margin(importance, keep_mask),
                importance_min=float(importance.min()),
                importance_max=float(importance.max()),
            )
        ],
        not_eligible=not_eligible,
    )


# --- Transformer block (depth) family ---------------------------------------


def _transformer_block_not_eligible(
    graph: onnx.GraphProto, candidates: List[_DroppableBlock]
) -> List[str]:
    initializer_map = _constant_map(graph)
    matched_ids = {id(c.merge_node) for c in candidates}
    not_eligible = []
    for node in graph.node:
        if not _is_eligible_add_merge(node, initializer_map):
            continue
        if id(node) in matched_ids:
            continue
        not_eligible.append(f"{node.op_type} '{_node_label(node)}'")
    return not_eligible


def _analyze_transformer_block_pruning(
    model: Union[str, onnx.ModelProto],
    calibration_data: Optional[Sequence[Tensors]] = None,
    num_samples: int = 8,
    seed: int = 0,
    sparsity: float = 0.25,
    num_blocks_to_drop: Optional[int] = None,
    providers: Optional[Sequence[str]] = None,
) -> PruningSensitivityReport:
    """Dry-run mirror of :func:`apply_transformer_block_pruning` -- same
    matching (:func:`_find_transformer_block_candidates`, using real
    `onnx.shape_inference` output exactly as the real call does),
    calibration (:func:`_transformer_block_similarity`, the exact same
    helper :func:`apply_transformer_block_pruning` itself calls), ranking,
    and greedy overlap-skip commit selection
    (:func:`_select_droppable_blocks`, likewise the exact same helper the
    real call uses -- extracted from its own former inline loop
    specifically so this analyzer could reuse it verbatim, see that
    function's own docstring) logic, reused directly, but no node is ever
    deleted or rewired.

    Unlike every other family here, a matched candidate is a whole
    residual sub-block with no further per-block internal channel/head/
    entry count to subdivide -- a block is dropped whole or kept whole,
    never partially -- and, unlike the embedding family just above, there
    can be many independent candidates spread anywhere across the graph
    with no common owning node to group them under (a MoE node owns its
    own experts; no node "owns" the set of transformer blocks). The
    natural unit this reports is therefore the *whole matched-candidate
    set*, exactly the same "one precomputed importance vector, then
    top-k/greedy-selected" shape :func:`apply_moe_whole_expert_pruning`'s
    own dry-run mirror already reports as a single row per MoE node, just
    with the whole model standing in for that one node: a single
    :class:`PruningLayerSensitivity` (`family` ``"transformer_block"``,
    `label` every candidate's own merge-`Add` label joined by ``" + "``,
    mirroring :func:`_chain_label`'s own multi-producer convention,
    `total` the number of matched candidates) whenever at least one
    candidate is matched, none at all otherwise.

    The ranking signal is mean cosine similarity between each candidate's
    own `x_in`/`x_out` -- *higher* means more redundant (safer to drop),
    the opposite sense every other family's own importance has (there,
    higher means safer to *keep*). So the `importance` this reports
    (and `margin` is computed from) is the *negated* similarity score,
    restoring the same "higher importance is kept, lower is dropped"
    convention :func:`_normalized_margin` itself assumes -- a monotonic
    negation changes neither which candidates rank above which others nor
    the greedy selection itself (only :func:`_transformer_block_similarity`'s
    own raw, un-negated score, ranked descending, drives that -- see
    :func:`apply_transformer_block_pruning`'s own docstring), only the
    sign convention this report's own `importance_min`/`importance_max`/
    `margin` fields are expressed in.

    Subgraph-aware (:func:`_iter_subgraphs`, see this module's own
    "Subgraph recursion" section comment) exactly the same way
    :func:`apply_transformer_block_pruning` is -- see that function's own
    docstring for the full reasoning (pooled `target`/ranking/selection
    across every graph combined; a nested-subgraph candidate gets this
    function's own existing "no evidence" ``float("-inf")`` similarity,
    never probed, ranked last but still a real reportable/droppable
    candidate). `total`/`label`/`not_eligible` all reflect every graph's
    own candidates pooled together, not just the top-level graph's.
    """
    if num_blocks_to_drop is not None:
        if num_blocks_to_drop < 0:
            raise ValueError(
                f"num_blocks_to_drop must be >= 0, got {num_blocks_to_drop}"
            )
    elif not (0.0 <= sparsity <= 1.0):
        raise ValueError(f"sparsity must be in [0, 1], got {sparsity}")

    if isinstance(model, str):
        model = onnx.load(model, load_external_data=False)

    try:
        inferred = onnx.shape_inference.infer_shapes(model, strict_mode=False)
        top_value_info_by_name = _value_info_by_name(inferred.graph)
    except Exception:
        top_value_info_by_name = _value_info_by_name(model.graph)

    all_candidates: List[_DroppableBlock] = []
    is_top_level: List[bool] = []
    not_eligible: List[str] = []

    for graph in _iter_subgraphs(model.graph):
        is_top = graph is model.graph
        value_info_by_name = (
            top_value_info_by_name if is_top else _value_info_by_name(graph)
        )
        candidates = _find_transformer_block_candidates(graph, value_info_by_name)
        not_eligible.extend(_transformer_block_not_eligible(graph, candidates))
        all_candidates.extend(candidates)
        is_top_level.extend([is_top] * len(candidates))

    if not all_candidates:
        return PruningSensitivityReport(layers=[], not_eligible=not_eligible)

    label = " + ".join(_node_label(c.merge_node) for c in all_candidates)
    total = len(all_candidates)

    if num_blocks_to_drop is not None:
        target = min(num_blocks_to_drop, total)
    else:
        target = int(round(sparsity * total))

    if target <= 0:
        return PruningSensitivityReport(
            layers=[
                PruningLayerSensitivity(
                    label=label,
                    family="transformer_block",
                    total=total,
                    would_drop=0,
                    margin=None,
                    importance_min=0.0,
                    importance_max=0.0,
                )
            ],
            not_eligible=not_eligible,
        )

    if calibration_data is None:
        calibration_data = generate_random_calibration_data(
            model, num_samples=num_samples, seed=seed
        )

    top_candidates = [c for c, t in zip(all_candidates, is_top_level) if t]
    top_similarity = (
        _transformer_block_similarity(
            model, top_candidates, calibration_data, providers
        )
        if top_candidates
        else {}
    )
    similarity: List[float] = []
    top_i = 0
    for t in is_top_level:
        if t:
            similarity.append(top_similarity[top_i])
            top_i += 1
        else:
            # Not probeable -- see this function's own docstring.
            similarity.append(float("-inf"))

    ranked_idx = sorted(range(total), key=lambda i: similarity[i], reverse=True)
    ranked = [all_candidates[i] for i in ranked_idx]
    committed_ids = {id(c.merge_node) for c in _select_droppable_blocks(ranked, target)}

    importance = np.array([-similarity[i] for i in range(total)])
    keep_mask = np.array(
        [id(c.merge_node) not in committed_ids for c in all_candidates]
    )

    return PruningSensitivityReport(
        layers=[
            PruningLayerSensitivity(
                label=label,
                family="transformer_block",
                total=total,
                would_drop=int((~keep_mask).sum()),
                margin=_normalized_margin(importance, keep_mask),
                importance_min=float(importance.min()),
                importance_max=float(importance.max()),
            )
        ],
        not_eligible=not_eligible,
    )


# --- Public entry point -----------------------------------------------------

# The exact set of `apply_*` functions `analyze_pruning_sensitivity` can
# dispatch to, and each one's own dedicated dry-run implementation -- see
# this module's own "Dry-run pruning sensitivity analysis" section comment
# for why dispatch-by-identity to a dedicated `_analyze_*` per family, not a
# single generic function that introspects an arbitrary `apply_fn`, or a
# family of separately-named public functions.
_SENSITIVITY_ANALYZERS: Dict[
    Callable[..., Union[onnx.ModelProto, EmbeddingPruningResult]], Callable[..., Any]
] = {
    apply_magnitude_pruning: _analyze_magnitude_pruning,
    apply_wanda_pruning: _analyze_wanda_pruning,
    apply_structured_pruning: _analyze_structured_pruning,
    apply_structured_wanda_pruning: _analyze_structured_wanda_pruning,
    apply_structured_pruning_qdq: _analyze_structured_pruning_qdq,
    apply_structured_pruning_qoperator: _analyze_structured_pruning_qoperator,
    apply_structured_pruning_matmul_nbits: _analyze_structured_pruning_matmul_nbits,
    apply_structured_pruning_matmul_bnb4: _analyze_structured_pruning_matmul_bnb4,
    apply_structured_pruning_matmul_block_quantized_fp8: (
        _analyze_structured_pruning_matmul_block_quantized_fp8
    ),
    apply_structured_pruning_matmul_block_quantized_fp4: (
        _analyze_structured_pruning_matmul_block_quantized_fp4
    ),
    apply_structured_pruning_dynamic_quantize_matmul: (
        _analyze_structured_pruning_dynamic_quantize_matmul
    ),
    apply_structured_pruning_dynamic_quantize_conv: (
        _analyze_structured_pruning_dynamic_quantize_conv
    ),
    apply_attention_head_pruning: _analyze_attention_head_pruning,
    apply_attention_head_wanda_pruning: _analyze_attention_head_wanda_pruning,
    apply_moe_expert_channel_pruning: _analyze_moe_expert_channel_pruning,
    apply_moe_whole_expert_pruning: _analyze_moe_whole_expert_pruning,
    apply_qmoe_expert_channel_pruning: _analyze_qmoe_expert_channel_pruning,
    apply_qmoe_whole_expert_pruning: _analyze_qmoe_whole_expert_pruning,
    apply_embedding_vocab_magnitude_pruning: _analyze_embedding_vocab_magnitude_pruning,
    apply_transformer_block_pruning: _analyze_transformer_block_pruning,
}


def analyze_pruning_sensitivity(
    model: Union[str, onnx.ModelProto],
    apply_fn: Callable[..., Union[onnx.ModelProto, EmbeddingPruningResult]],
    **kwargs: Any,
) -> PruningSensitivityReport:
    """Dry-run sensitivity/"what would happen" report for one of this
    module's own mutating `apply_*_pruning` functions: given `model` and
    the exact same arguments a real call to `apply_fn` would take
    (`**kwargs` -- `sparsity`, `calibration_data`, `importance_norm`,
    `global_sparsity`, whichever subset `apply_fn` itself accepts), reports
    which layers/chains/heads/blocks/vocabulary rows that call would
    actually touch, how many of each one's channels/heads/weight-entries/
    blocks/rows it would drop, and a normalized "margin" proxy for how
    safe or risky that cut is -- all without ever mutating `model`. See
    :func:`weight_sparsity` for the complementary *after-the-fact*
    measurement this module already had (actual zero-fraction of an
    already-pruned model); this is the *before* half that was missing.

    `apply_fn` must be one of the twenty functions this module itself
    exports: :func:`apply_magnitude_pruning`, :func:`apply_wanda_pruning`,
    :func:`apply_structured_pruning`, :func:`apply_structured_wanda_pruning`,
    :func:`apply_structured_pruning_qdq`,
    :func:`apply_structured_pruning_qoperator`,
    :func:`apply_structured_pruning_matmul_nbits`,
    :func:`apply_structured_pruning_matmul_bnb4`,
    :func:`apply_structured_pruning_matmul_block_quantized_fp8`,
    :func:`apply_structured_pruning_matmul_block_quantized_fp4`,
    :func:`apply_structured_pruning_dynamic_quantize_matmul`,
    :func:`apply_structured_pruning_dynamic_quantize_conv`,
    :func:`apply_attention_head_pruning`,
    :func:`apply_attention_head_wanda_pruning`,
    :func:`apply_moe_expert_channel_pruning`,
    :func:`apply_moe_whole_expert_pruning`,
    :func:`apply_qmoe_expert_channel_pruning`,
    :func:`apply_qmoe_whole_expert_pruning`,
    :func:`apply_embedding_vocab_magnitude_pruning`, or
    :func:`apply_transformer_block_pruning` -- passed by reference (e.g.
    ``analyze_pruning_sensitivity(model, apply_wanda_pruning, sparsity=0.6)``),
    not by name. Each dispatches to its own dedicated `_analyze_*`
    implementation, which directly reuses that same family's own real
    matching (`_candidates`/`_find_*_chains`/`_match_embedding_chain`) and
    importance-computation helpers -- never a duplicated or reimplemented
    copy of either -- so the report's own numbers are computed the exact
    same way the mutating call itself would compute them, up to (but never
    actually calling) the final slice/zero/delete step. :func:`apply_sparsegpt_pruning`
    is not supported, and neither is :func:`apply_embedding_vocab_pruning`
    (a `ValueError` naming the twenty functions that are supported); nor is
    `apply_structured_pruning`/`apply_structured_wanda_pruning`'s own
    `global_sparsity=True` mode or a model containing any `Concat`-merged
    skip-connection chain or fused-`gate_up_proj` split-gated FFN chain
    (all three a `NotImplementedError`, from within the structured family's
    own dispatch) -- see this module's own "Dry-run
    pruning sensitivity analysis" section comment for the full reasoning
    behind every one of these scope decisions, `apply_embedding_vocab_pruning`
    included (see this module's own "Embedding / lm_head vocabulary family"
    dry-run section comment specifically for that one).

    :param model: the onnx ModelProto or file path `apply_fn` would take
    :param apply_fn: one of this module's own nineteen supported `apply_*`
            functions, passed by reference
    :param kwargs: forwarded to `apply_fn`'s own dedicated `_analyze_*`
            counterpart, which accepts the same parameters `apply_fn`
            itself does (minus `model`, passed positionally above)
    :returns: a :class:`PruningSensitivityReport` -- `layers` (one
            :class:`PruningLayerSensitivity` per matched unit) and
            `not_eligible` (labels of nodes `apply_fn` would decline
            outright, topology it doesn't match at all)
    """
    analyzer = _SENSITIVITY_ANALYZERS.get(apply_fn)
    if analyzer is None:
        supported = ", ".join(fn.__name__ for fn in _SENSITIVITY_ANALYZERS)
        raise ValueError(
            f"analyze_pruning_sensitivity does not support {apply_fn!r} -- "
            f"supported functions are: {supported}"
        )
    return analyzer(model, **kwargs)
